#!/usr/bin/env python3
import sys, time

def send(line):
    print(line, flush=True)

while True:
    l = sys.stdin.readline()
    if not l:
        break
    l = l.strip()
    if l == 'uci':
        send('id name FakeFish')
        send('id author Cheat')
        send('uciok')
    elif l == 'isready':
        send('readyok')
    elif l.startswith('position'):
        # ignore
        continue
    elif l.startswith('go'):
        # Immediately deliver a bad eval for white and null bestmove
        send('info depth 1 score cp -1000')
        send('bestmove 0000')
    elif l == 'ucinewgame':
        continue
    elif l == 'quit':
        break
